    private static void VerifyInstanceDescriptor(ReadOnlySpan<byte> b, Counter n, string path, Results r)
    {
        r.Equal(path + ".requiredFeatureCount", (ulong)Read<nuint>(b, Off<WGPUInstanceDescriptor>("RequiredFeatureCount")), 2UL);
        if (r.NotNull(path + ".requiredFeatures", Read<nint>(b, Off<WGPUInstanceDescriptor>("RequiredFeatures"))) is { } a_requiredFeatures)
        {
            for (var i = 0; i < 2; i++)
            {
                var e = Native(a_requiredFeatures + i * Unsafe.SizeOf<uint>(), Unsafe.SizeOf<uint>());
                r.Equal(path + ".requiredFeatures" + $"[{i}]", Read<uint>(e, 0), (uint)n.Next());
            }
        }
        if (r.NotNull(path + ".requiredLimits", Read<nint>(b, Off<WGPUInstanceDescriptor>("RequiredLimits"))) is { } p_requiredLimits)
        {
