    private static TextureDescriptor MakeTextureDescriptor(Counter n) => new()
    {
        Label = n.String(),
        Usage = (TextureUsage)n.Next(),
        Dimension = (TextureDimension)n.Next(),
        Size = MakeExtent3D(n),
        Format = (TextureFormat)n.Next(),
        MipLevelCount = (uint)n.Next(),
        SampleCount = (uint)n.Next(),
        ViewFormats = new TextureFormat[] { (TextureFormat)n.Next(), (TextureFormat)n.Next() },
        TextureBindingViewDimension = MakeTextureBindingViewDimension(n),
    };

    private static void VerifyTextureDescriptor(ReadOnlySpan<byte> b, Counter n, string path, Results r)
    {
        r.String(path + ".label", b, Off<WGPUTextureDescriptor>("Label"), n);
        r.Equal(path + ".usage", Read<ulong>(b, Off<WGPUTextureDescriptor>("Usage")), (ulong)n.Next());
        r.Equal(path + ".dimension", Read<uint>(b, Off<WGPUTextureDescriptor>("Dimension")), (uint)n.Next());
        VerifyExtent3D(b[Off<WGPUTextureDescriptor>("Size")..], n, path + ".size", r);
        r.Equal(path + ".format", Read<uint>(b, Off<WGPUTextureDescriptor>("Format")), (uint)n.Next());
        r.Equal(path + ".mipLevelCount", Read<uint>(b, Off<WGPUTextureDescriptor>("MipLevelCount")), (uint)n.Next());
        r.Equal(path + ".sampleCount", Read<uint>(b, Off<WGPUTextureDescriptor>("SampleCount")), (uint)n.Next());
        r.Equal(path + ".viewFormatCount", (ulong)Read<nuint>(b, Off<WGPUTextureDescriptor>("ViewFormatCount")), 2UL);
        if (r.NotNull(path + ".viewFormats", Read<nint>(b, Off<WGPUTextureDescriptor>("ViewFormats"))) is { } a_viewFormats)
        {
            for (var i = 0; i < 2; i++)
            {
                var e = Native(a_viewFormats + i * Unsafe.SizeOf<uint>(), Unsafe.SizeOf<uint>());
                r.Equal(path + ".viewFormats" + $"[{i}]", Read<uint>(e, 0), (uint)n.Next());
            }
        }
        var links = r.Chain(path + ".nextInChain", Read<nint>(b, Off<WGPUTextureDescriptor>("NextInChain")), 1);
        if (r.Link(path + ".TextureBindingViewDimension", links, (uint)SType.TextureBindingViewDimension) is { } l_TextureBindingViewDimension)
        {
            VerifyTextureBindingViewDimension(Native(l_TextureBindingViewDimension, Unsafe.SizeOf<WGPUTextureBindingViewDimension>()), n, path + ".TextureBindingViewDimension", r);
        }
    }

