    private static TextureViewDescriptor MakeTextureViewDescriptor(Counter n) => new()
    {
        Label = n.String(),
        Format = (TextureFormat)n.Next(),
        Dimension = (TextureViewDimension)n.Next(),
        BaseMipLevel = (uint)n.Next(),
        MipLevelCount = (uint)n.Next(),
        BaseArrayLayer = (uint)n.Next(),
        ArrayLayerCount = (uint)n.Next(),
        Aspect = (TextureAspect)n.Next(),
        Usage = (TextureUsage)n.Next(),
        TextureComponentSwizzleDescriptor = MakeTextureComponentSwizzleDescriptor(n),
    };

    private static void VerifyTextureViewDescriptor(ReadOnlySpan<byte> b, Counter n, string path, Results r)
    {
        r.String(path + ".label", b, Off<WGPUTextureViewDescriptor>("Label"), n);
        r.Equal(path + ".format", Read<uint>(b, Off<WGPUTextureViewDescriptor>("Format")), (uint)n.Next());
        r.Equal(path + ".dimension", Read<uint>(b, Off<WGPUTextureViewDescriptor>("Dimension")), (uint)n.Next());
        r.Equal(path + ".baseMipLevel", Read<uint>(b, Off<WGPUTextureViewDescriptor>("BaseMipLevel")), (uint)n.Next());
        r.Equal(path + ".mipLevelCount", Read<uint>(b, Off<WGPUTextureViewDescriptor>("MipLevelCount")), (uint)n.Next());
        r.Equal(path + ".baseArrayLayer", Read<uint>(b, Off<WGPUTextureViewDescriptor>("BaseArrayLayer")), (uint)n.Next());
        r.Equal(path + ".arrayLayerCount", Read<uint>(b, Off<WGPUTextureViewDescriptor>("ArrayLayerCount")), (uint)n.Next());
        r.Equal(path + ".aspect", Read<uint>(b, Off<WGPUTextureViewDescriptor>("Aspect")), (uint)n.Next());
        r.Equal(path + ".usage", Read<ulong>(b, Off<WGPUTextureViewDescriptor>("Usage")), (ulong)n.Next());
        var links = r.Chain(path + ".nextInChain", Read<nint>(b, Off<WGPUTextureViewDescriptor>("NextInChain")), 1);
        if (r.Link(path + ".TextureComponentSwizzleDescriptor", links, (uint)SType.TextureComponentSwizzleDescriptor) is { } l_TextureComponentSwizzleDescriptor)
        {
            VerifyTextureComponentSwizzleDescriptor(Native(l_TextureComponentSwizzleDescriptor, Unsafe.SizeOf<WGPUTextureComponentSwizzleDescriptor>()), n, path + ".TextureComponentSwizzleDescriptor", r);
        }
    }

