    private static VertexBufferLayout MakeVertexBufferLayout(Counter n) => new()
    {
        StepMode = (VertexStepMode)n.Next(),
        ArrayStride = (ulong)n.Next(),
        Attributes = new VertexAttribute[] { MakeVertexAttribute(n), MakeVertexAttribute(n) },
    };

    private static void VerifyVertexBufferLayout(ReadOnlySpan<byte> b, Counter n, string path, Results r)
    {
        r.Equal(path + ".stepMode", Read<uint>(b, Off<WGPUVertexBufferLayout>("StepMode")), (uint)n.Next());
        r.Equal(path + ".arrayStride", Read<ulong>(b, Off<WGPUVertexBufferLayout>("ArrayStride")), (ulong)n.Next());
        r.Equal(path + ".attributeCount", (ulong)Read<nuint>(b, Off<WGPUVertexBufferLayout>("AttributeCount")), 2UL);
        if (r.NotNull(path + ".attributes", Read<nint>(b, Off<WGPUVertexBufferLayout>("Attributes"))) is { } a_attributes)
        {
            for (var i = 0; i < 2; i++)
            {
                var e = Native(a_attributes + i * Unsafe.SizeOf<WGPUVertexAttribute>(), Unsafe.SizeOf<WGPUVertexAttribute>());
                VerifyVertexAttribute(e, n, path + ".attributes" + $"[{i}]", r);
            }
        }
        r.Equal(path + ".nextInChain", Read<nint>(b, Off<WGPUVertexBufferLayout>("NextInChain")), 0);
    }

    private static void DefaultsVertexBufferLayout(ReadOnlySpan<byte> ours, ReadOnlySpan<byte> init, string path, Results r)
    {
        r.Same(path + ".nextInChain", Read<nint>(ours, Off<WGPUVertexBufferLayout>("NextInChain")), Read<nint>(init, Off<WGPUVertexBufferLayout>("NextInChain")));
        r.Same(path + ".stepMode", Read<uint>(ours, Off<WGPUVertexBufferLayout>("StepMode")), Read<uint>(init, Off<WGPUVertexBufferLayout>("StepMode")));
        r.Same(path + ".arrayStride", Read<ulong>(ours, Off<WGPUVertexBufferLayout>("ArrayStride")), Read<ulong>(init, Off<WGPUVertexBufferLayout>("ArrayStride")));
        r.Same(path + ".attributeCount", Read<nuint>(ours, Off<WGPUVertexBufferLayout>("AttributeCount")), Read<nuint>(init, Off<WGPUVertexBufferLayout>("AttributeCount")));
        r.Same(path + ".attributes", Read<nint>(ours, Off<WGPUVertexBufferLayout>("Attributes")), Read<nint>(init, Off<WGPUVertexBufferLayout>("Attributes")));
    }

    private static VertexState MakeVertexState(Counter n) => new()
    {
        Module = new global::Olve.WebGPU.ShaderModule(HandleBase + n.Next()),
        EntryPoint = n.String(),
        Constants = new ConstantEntry[] { MakeConstantEntry(n), MakeConstantEntry(n) },
        Buffers = new VertexBufferLayout[] { MakeVertexBufferLayout(n), MakeVertexBufferLayout(n) },
    };

    private static void VerifyVertexState(ReadOnlySpan<byte> b, Counter n, string path, Results r)
    {
        r.Equal(path + ".module", Read<nint>(b, Off<WGPUVertexState>("Module")), HandleBase + n.Next());
        r.String(path + ".entryPoint", b, Off<WGPUVertexState>("EntryPoint"), n);
        r.Equal(path + ".constantCount", (ulong)Read<nuint>(b, Off<WGPUVertexState>("ConstantCount")), 2UL);
        if (r.NotNull(path + ".constants", Read<nint>(b, Off<WGPUVertexState>("Constants"))) is { } a_constants)
        {
            for (var i = 0; i < 2; i++)
            {
                var e = Native(a_constants + i * Unsafe.SizeOf<WGPUConstantEntry>(), Unsafe.SizeOf<WGPUConstantEntry>());
                VerifyConstantEntry(e, n, path + ".constants" + $"[{i}]", r);
            }
        }
        r.Equal(path + ".bufferCount", (ulong)Read<nuint>(b, Off<WGPUVertexState>("BufferCount")), 2UL);
        if (r.NotNull(path + ".buffers", Read<nint>(b, Off<WGPUVertexState>("Buffers"))) is { } a_buffers)
        {
            for (var i = 0; i < 2; i++)
            {
                var e = Native(a_buffers + i * Unsafe.SizeOf<WGPUVertexBufferLayout>(), Unsafe.SizeOf<WGPUVertexBufferLayout>());
                VerifyVertexBufferLayout(e, n, path + ".buffers" + $"[{i}]", r);
            }
        }
        r.Equal(path + ".nextInChain", Read<nint>(b, Off<WGPUVertexState>("NextInChain")), 0);
    }

